defmodule Absinthe.Pipeline do
  alias Absinthe.Phase
  @type t :: [Phase.t()]
  @type phase_config_t :: Phase.t() | {Phase.t(), any()}

  @doc """
  Return the part of a pipeline before a specific phase.

  ## Examples

      iex> Pipeline.before([A, B, C], B)
      [A]
  """
  @spec before(t, phase_config_t) :: t
  def before(pipeline, phase) do
    Enum.take_while(pipeline, &match_phase?(_, phase))
  end

  @spec match_phase?(Phase.t(), phase_config_t) :: boolean
  def match_phase?(phase, phase), do: true
  def match_phase?(phase, {phase, _}) when is_atom(phase), do: true
  def match_phase?(_, _), do: false
end

def replace(pipeline, phase, replacement) do
  {replacement_phase, replacement_options} =
    case replacement do
      {p, opts} when is_list(opts) -> {p, opts}
      p -> {p, []}
    end

  Enum.map(pipeline, fn
    ^phase ->
      {replacement_phase, replacement_options}

    {p, opts} when is_atom(p) and p == phase ->
      {replacement_phase, replacement_options}

    item ->
      item
  end)
end

